import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    expected_width = 5
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    columns = []
    for record in reader:
        if any(value.strip() for value in record):
            columns = record
            break
    else:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(expected_width, len(columns))
    for row in rows:
        width = max(width, len(row))

    used_names = set(columns)
    for index in range(len(columns) + 1, width + 1):
        base = f"column_{index}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
